62	// The single source of truth for which item types MHPCO insures, and at what
63	// price. Every insurable type carries both a base premium (what the customer
64	// pays) and an insurance value (what MHPCO undertakes to cover).
65	const PRICE_LIST: Record<string, PriceListEntry> = {
66	  sword: { basePremium: 100, insuranceValue: 1000 },
67	  amulet: { basePremium: 60, insuranceValue: 600 },
68	  staff: { basePremium: 80, insuranceValue: 800 },
69	  potion: { basePremium: 40, insuranceValue: 400 },
70	  rune: { basePremium: 25, insuranceValue: 250 },
71	  moonstone: { basePremium: 25, insuranceValue: 250 },
72	};
73	
74	const BLOCK_SIZE = 3;
75	const BLOCK_PREMIUM = 60;
76	
77	const isBlock = (sameTypeItems: Item[]): boolean =>
78	  sameTypeItems.length === BLOCK_SIZE;
79	
80	const rejectUnknownItemType = (type: string): never => {
81	  throw new Error(`Unknown item type: ${type}`);
82	};
83	
84	const priceListEntryOfItem = (item: Item): PriceListEntry =>
85	  PRICE_LIST[item.type] ?? rejectUnknownItemType(item.type);
86	
87	const basePremiumOfItem = (item: Item): number =>
88	  priceListEntryOfItem(item).basePremium;
89	
90	const sumOverItems = (items: Item[], valueOfItem: (item: Item) => number) =>
91	  items.reduce((sum, item) => sum + valueOfItem(item), 0);
92	
93	const sumOfItemBasePremiums = (items: Item[]): number =>
94	  sumOverItems(items, basePremiumOfItem);
95	
96	const groupByType = (items: Item[]): Item[][] =>
97	  Object.values(
98	    items.reduce<Record<string, Item[]>>(
99	      (groups, item) => ({
100	        ...groups,
101	        [item.type]: [...(groups[item.type] ?? []), item],
102	      }),
103	      {},
104	    ),
105	  );
106	
107	const basePremiumOfGroup = (items: Item[]): number =>
108	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
109	
110	const policyBasePremium = (items: Item[]): number =>
111	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
112	
113	const CURSED_SURCHARGE_RATE = 0.5;
114	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
115	
116	const HIGH_ENCHANTMENT_THRESHOLD = 5;
117	
118	const isCursed = (item: Item): boolean => item.cursed === true;
119	
120	const UNENCHANTED = 0;
121	
122	const enchantmentOf = (item: Item): number => item.enchantment ?? UNENCHANTED;
123	
124	const isHighlyEnchanted = (item: Item): boolean =>
125	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
126	
127	const NO_SURCHARGE_RATE = 0;
128	
129	const surchargeRateOfItem = (item: Item): number =>
130	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
131	  (isHighlyEnchanted(item)
132	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
133	    : NO_SURCHARGE_RATE);
134	
135	const surchargeOfItem = (item: Item): number =>
136	  basePremiumOfItem(item) * surchargeRateOfItem(item);
137	
138	const sumOfItemSurcharges = (items: Item[]): number =>
139	  sumOverItems(items, surchargeOfItem);
140	
141	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
142	
143	const firstInsuranceSurcharge = (basePremium: number): number =>
144	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
145	
146	const roundPremiumInMHPCOsFavour = (premium: number): number =>
147	  Math.ceil(premium);
148	
149	const LOYALTY_DISCOUNT_RATE = 0.2;
150	const LOYALTY_YEARS_THRESHOLD = 2;
151	const NO_DISCOUNT = 0;
152	
153	const isLoyal = (customer: Customer): boolean =>
154	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
155	
156	const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
157	  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;
158	
159	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
160	
161	const isFollowUpContract = (previousQuoteCount: number): boolean =>
162	  previousQuoteCount > 0;
163	
164	const followUpContractDiscount = (
165	  previousQuoteCount: number,
166	  basePremium: number,
167	): number =>
168	  isFollowUpContract(previousQuoteCount)
169	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
170	    : NO_DISCOUNT;
171	
172	const quote = (
173	  items: Item[],
174	  customer: Customer,
175	  previousQuoteCount: number,
176	): QuoteResult => {
177	  const basePremium = policyBasePremium(items);
178	  const surcharges =
179	    sumOfItemSurcharges(items) + firstInsuranceSurcharge(basePremium);
180	  const discounts =
181	    loyaltyDiscount(customer, basePremium) +
182	    followUpContractDiscount(previousQuoteCount, basePremium);
183	  return {
184	    premium: roundPremiumInMHPCOsFavour(
185	      PROCESSING_FEE + basePremium + surcharges - discounts,
186	    ),
187	  };
188	};
189	
190	const DEDUCTIBLE = 100;
191	const CAP_FACTOR = 2;
192	
193	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
194	const HALF_REIMBURSEMENT_RATE = 0.5;
195	const FULL_REIMBURSEMENT_RATE = 1;
196	
197	const rejectItemNotInPolicy = (type: string): never => {
198	  throw new Error(`Item not insured by this policy: ${type}`);
199	};
200	
201	const reserveItemForDamage = (damage: Damage, unclaimedItems: Item[]): Item =>
202	  unclaimedItems.find((item) => item.type === damage.itemType) ??
203	  rejectItemNotInPolicy(damage.itemType);
204	
205	const isDeeplyEnchanted = (item: Item): boolean =>
206	  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
207	
208	const reimbursementRateOfItem = (item: Item): number =>
209	  isDeeplyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
210	
211	const rejectNegativeDamageAmount = (amount: number): never => {
212	  throw new Error(`Negative damage amount: ${amount}`);
213	};
214	
215	const damagedAmount = (damage: Damage): number =>
216	  damage.amount >= 0 ? damage.amount : rejectNegativeDamageAmount(damage.amount);
217	
218	const payoutOfDamage = (damage: Damage, item: Item): number =>
219	  damagedAmount(damage) * reimbursementRateOfItem(item) - DEDUCTIBLE;
220	
221	const withoutItem = (items: Item[], item: Item): Item[] =>
222	  items.filter((candidate) => candidate !== item);
223	
224	interface ClaimedDamage {
225	  damage: Damage;
226	  item: Item;
227	}
228	
229	const assignDistinctItems = (
230	  damages: Damage[],
231	  policyItems: Item[],
232	): ClaimedDamage[] =>
233	  damages.reduce<{ claimed: ClaimedDamage[]; unclaimed: Item[] }>(
234	    ({ claimed, unclaimed }, damage) => {
235	      const item = reserveItemForDamage(damage, unclaimed);
236	      return {
237	        claimed: [...claimed, { damage, item }],
238	        unclaimed: withoutItem(unclaimed, item),
239	      };
240	    },
241	    { claimed: [], unclaimed: policyItems },
242	  ).claimed;
243	
244	const payoutOfIncident = (incident: Incident, policyItems: Item[]): number =>
245	  assignDistinctItems(incident.damages, policyItems).reduce(
246	    (sum, { damage, item }) => sum + payoutOfDamage(damage, item),
247	    0,
248	  );
249	
250	const declaredInsuranceValueOfItem = (item: Item): number =>
251	  priceListEntryOfItem(item).insuranceValue;
252	
253	const insuranceSum = (items: Item[]): number =>
254	  sumOverItems(items, declaredInsuranceValueOfItem);
255	
256	const capOfPolicy = (policyItems: Item[]): number =>
257	  CAP_FACTOR * insuranceSum(policyItems);
258	
259	const roundPayoutInMHPCOsFavour = (payout: number): number =>
260	  Math.floor(payout);
261	
262	const claim = (
263	  incident: Incident,
264	  policyItems: Item[],
265	  availableCap: number,
266	): ClaimResult => {
267	  const payout = roundPayoutInMHPCOsFavour(
268	    Math.min(payoutOfIncident(incident, policyItems), availableCap),
269	  );
270	  return {
271	    payout,
272	    remainingCap: availableCap - payout,
273	  };
274	};
275	
276	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
277	
278	const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] => {
279	  const step = steps[policy];
280	  if (!isQuoteStep(step)) throw new Error(`Not a quote step: ${policy}`);
281	  return step.items;
282	};
283	
284	const quoteCountBefore = (steps: Step[], stepIndex: number): number =>
285	  steps.slice(0, stepIndex).filter(isQuoteStep).length;
286	
287	type RemainingCaps = Record<number, number>;
288	
289	const availableCapOfPolicy = (
290	  remainingCaps: RemainingCaps,
291	  policyItems: Item[],
292	  policy: number,
293	): number => remainingCaps[policy] ?? capOfPolicy(policyItems);
294	
295	export const runScenario = (scenario: Scenario): ScenarioResult => {
296	  const remainingCaps: RemainingCaps = {};
297	  const results = scenario.steps.map((step, stepIndex) => {
298	    if (isQuoteStep(step)) {
299	      return quote(
300	        step.items,
301	        scenario.customer,
302	        quoteCountBefore(scenario.steps, stepIndex),
303	      );
304	    }
305	    const policyItems = insuredItemsOfPolicy(scenario.steps, step.policy);
306	    const result = claim(
307	      step.incident,
308	      policyItems,
309	      availableCapOfPolicy(remainingCaps, policyItems, step.policy),
310	    );
311	    remainingCaps[step.policy] = result.remainingCap;
312	    return result;
313	  });
314	  return { results };
315	};
